@push('styles')
<link rel="stylesheet" href="{{ asset('css/qms-archives.css') }}">
@endpush
<section class="qms-explorer" x-data="qmsArchives">
    <header class="qms-heading"><div><p class="qms-eyebrow">CET document repository</p><h2>QMS Archives</h2><p>Browse authorized records by office, department, and document category.</p></div><div class="qms-actions"><button type="button" class="qms-button" x-show="tree.canManageOrganization" x-cloak @click="manageOrganization">Manage responsibilities</button><button type="button" class="qms-button qms-gold" x-show="canCreate" x-cloak @click="create()">+ Add record</button></div></header>
    <p class="qms-alert" role="alert" x-show="error" x-cloak x-text="error"></p><p class="qms-notice" role="status" x-show="notice" x-cloak x-text="notice"></p>
    <p class="qms-notice" x-show="tree.ownershipReviewRequired" x-cloak>Your existing department assignment needs an ownership review. A Super Admin must confirm its correct department before those archive records can be shown.</p>
    <div class="qms-workspace">
        <aside class="qms-sidebar" :class="{'is-expanded': navExpanded}" aria-label="Authorized archive folders"><button type="button" class="qms-mobile-toggle" @click="navExpanded = !navExpanded" :aria-expanded="navExpanded" x-text="navExpanded ? 'Hide folders' : 'Browse folders'"></button><button type="button" class="qms-tree-root" @click="navigate()" :aria-current="!collegeId ? 'page' : null">▣ <span x-text="tree.campus || 'USTP Claveria Campus'"></span></button>
            <template x-for="college in tree.colleges" :key="college._id"><div class="qms-college"><button type="button" @click="navigate(college._id)" x-text="college.name"></button><template x-for="folder in tree.units.filter(unit => unit.collegeId === college._id)" :key="folder._id"><button type="button" class="qms-tree-unit" :class="{'is-selected': unitId === folder._id}" @click="navigate(college._id, folder._id)"><span aria-hidden="true">▱</span><span x-text="folder.name"></span><small x-text="folder.count"></small></button></template></div></template>
            <p class="qms-scope-note">Only folders and counts within your authorized scope are shown. The Office of the Dean is a college office.</p>
        </aside>
        <main class="qms-main">
            <nav class="qms-breadcrumbs" aria-label="Archive breadcrumb"><button type="button" @click="navigate()">Campus</button><template x-if="college"><span> / <button type="button" @click="navigate(collegeId)" x-text="college.code"></button></span></template><template x-if="unit"><span> / <button type="button" @click="navigate(collegeId, unitId)" x-text="unit.name"></button></span></template><template x-for="crumb in categoryTrail" :key="crumb._id"><span> / <button type="button" @click="navigate(collegeId, unitId, crumb._id)" :aria-current="crumb._id === categoryId ? 'page' : null" x-text="crumb.name"></button></span></template></nav>
            <div class="qms-toolbar"><label class="qms-search"><span class="qms-sr-only">Search authorized documents</span><input type="search" placeholder="Search title, reference, or file code…" x-model="search" @input.debounce.350ms="load(true)"></label><label><span class="qms-sr-only">Document type</span><select x-model="recordType" @change="load(true)"><option value="">All document types</option value="file">Digital files</option><option value="digital-reference">Document references</option><option value="physical-original">Physical originals</option></select></label><span class="qms-count" x-text="`${meta.total || 0} authorized records`"></span></div>
            <div class="qms-folders" x-show="!unitId"><template x-for="folder in folders" :key="folder._id"><button type="button" class="qms-folder" @click="navigate(folder.collegeId, folder._id)"><span class="qms-folder-icon" aria-hidden="true">▰</span><strong x-text="folder.name"></strong><small x-text="`${folder.unitType === 'college_office' ? 'College office' : 'Department'} · ${folder.count} records`"></small></button></template></div>
            <div class="qms-category-header" x-show="unitId && categories.length"><h3>Document categories</h3><small>Provisional organization · configurable by Super Admin</small></div>
            <div class="qms-folders qms-categories" x-show="unitId"><template x-for="folder in categories" :key="folder._id"><div class="qms-category-card"><button type="button" class="qms-folder" @click="navigate(collegeId, unitId, folder._id)"><span class="qms-folder-icon" aria-hidden="true">▰</span><strong><span x-text="folder.code"></span> <span x-text="folder.name"></span></strong><small x-text="`${folder.counts[unitId] || 0} authorized records`"></small></button><button type="button" class="qms-configure" x-show="tree.canManageOrganization" @click="configureCategory(folder)" :aria-label="`Rename ${folder.name}`">Rename</button></div></template></div>
            <div class="qms-doc-header"><h3 x-text="category?.name || 'Documents'"></h3><button type="button" class="qms-link" x-show="categoryId" @click="navigate(collegeId, unitId)">All categories</button></div>
            <p class="qms-loading" role="status" x-show="loading">Loading authorized archives…</p>
            <div class="qms-documents" x-show="!loading"><template x-for="document in documents" :key="document._id"><article class="qms-document"><div class="qms-doc-top"><span class="qms-type" x-text="type(document.recordType)"></span><span class="qms-version" x-text="`v${document.versionNumber}`"></span></div><h4 x-text="document.title"></h4><p class="qms-doc-reference" x-text="document.fileCode"></p><p class="qms-document-description" x-text="document.description || document.documentReference || document.physicalLocation || 'Authorized archived evidence'"></p><dl><div><dt>Department / office</dt><dd x-text="document.departmentName"></dd></div><div><dt>Owner</dt><dd x-text="document.uploadedBy"></dd></div><div><dt>Recorded</dt><dd x-text="date(document.createdAt)"></dd></div></dl><div class="qms-doc-actions"><button type="button" class="qms-button" @click="inspect(document)">Details &amp; history</button><a x-show="document.canDownload" class="qms-button qms-gold" :href="`/api/v1/archives/${document._id}/download`" :data-file-name="document.originalName" data-evidence-preview>Preview</a></div></article></template></div>
            <div class="qms-empty" x-show="!loading && !documents.length"><span aria-hidden="true">▱</span><h3>No authorized records here yet</h3><p x-text="search || recordType ? 'Try a different search or document type.' : 'Choose an authorized folder or add a permitted document, reference, or physical-original record.'"></p><button type="button" class="qms-button" x-show="search || recordType" @click="search=''; recordType=''; load(true)">Clear filters</button></div>
            <nav class="qms-pagination" aria-label="Archive pages" x-show="meta.lastPage > 1"><button type="button" class="qms-button" :disabled="page <= 1" @click="page--; load()">Previous</button><span x-text="`Page ${page} of ${meta.lastPage}`"></span><button type="button" class="qms-button" :disabled="page >= meta.lastPage" @click="page++; load()">Next</button></nav>
        </main>
    </div>
    <dialog class="qms-dialog" x-ref="details" aria-labelledby="qms-detail-title"><template x-if="detail"><div><header><div><p class="qms-eyebrow">Document details</p><h2 id="qms-detail-title" x-text="detail.title"></h2></div><button type="button" class="qms-close" @click="$refs.details.close()" aria-label="Close document details">×</button></header><div class="qms-dialog-body"><p class="qms-alert" role="alert" x-show="error" x-text="error"></p><p class="qms-notice" role="status" x-show="notice" x-text="notice"></p><div class="qms-detail-grid"><section><h3>Record information</h3><dl class="qms-metadata"><dt>File code</dt><dd x-text="detail.fileCode"></dd><dt>Presentation</dt><dd x-text="type(detail.recordType)"></dd><dt>Department / office</dt><dd x-text="detail.departmentName"></dd><dt>Owner</dt><dd x-text="detail.uploadedBy"></dd><dt>Version</dt><dd x-text="detail.versionNumber"></dd><dt x-show="detail.documentCode">Document code</dt><dd x-show="detail.documentCode" x-text="detail.documentCode"></dd><dt x-show="detail.revisionLabel">Revision</dt><dd x-show="detail.revisionLabel" x-text="detail.revisionLabel"></dd><dt x-show="detail.effectiveDate">Effective date</dt><dd x-show="detail.effectiveDate" x-text="detail.effectiveDate"></dd><dt>Visibility</dt><dd x-text="label(detail.visibility || 'owner')"></dd></dl><p x-text="detail.description"></p><template x-if="detail.documentReference"><div class="qms-reference"><strong>Document reference</strong><p x-text="detail.documentReference"></p></div></template><template x-if="detail.recordType === 'physical-original'"><div class="qms-reference"><strong>Physical original · handwritten signature required</strong><p x-text="detail.physicalLocation"></p><p x-text="`Signature verification: ${label(detail.signatureStatus || 'not_verified')}`"></p><small>The authorized reviewer verifies the original through the existing evidence workflow.</small></div></template><div class="qms-actions"><a x-show="detail.canDownload" class="qms-button qms-gold" :href="`/api/v1/archives/${detail._id}/download`" :data-file-name="detail.originalName" data-evidence-preview>Preview file</a><a x-show="detail.canDownload" class="qms-button" :href="`/api/v1/archives/${detail._id}/download`">Download</a><button type="button" class="qms-button" x-show="detail.canManage" @click="create(detail)">Add version</button></div>
            <section class="qms-permissions" x-show="detail.canManage"><h3>Document access</h3><form @submit.prevent="permissions"><label>Visibility<select x-model="detail.visibility"><option value="owner">Owner and explicitly permitted accounts</option><option value="department">Authorized department accounts</option><option value="college">Authorized college responsibilities and department accounts</option><option value="restricted">Restricted · owner and explicitly permitted accounts</option></select></label><fieldset><legend>Explicitly permitted accounts</legend><template x-for="account in accessOptions.accounts" :key="account._id"><label class="qms-checkbox"><input type="checkbox" :value="account._id" x-model="detail.accessUserIds"><span x-text="account.name"></span></label></template><small>Organizational scope is still required.</small></fieldset><label class="qms-checkbox"><input type="checkbox" x-model="detail.downloadAllowed">Allow authorized file preview and download</label><button type="submit" class="qms-button" :disabled="saving">Save permissions</button></form><form class="qms-share" @submit.prevent="share()"><label>Share with an assigned audit<select x-model="auditId" required><option value="">Select an assigned audit</option><template x-for="audit in accessOptions.audits" :key="audit._id"><option :value="audit._id" x-text="audit.reference"></option></template></select></label><button type="submit" class="qms-button" :disabled="saving">Share evidence</button><small>Only the assigned auditor receives access. A new version needs a new share.</small></form><template x-for="id in detail.sharedAuditIds || []" :key="id"><div class="qms-share-row"><span x-text="accessOptions.audits.find(audit => audit._id === id)?.reference || 'Previously assigned audit'"></span><button type="button" class="qms-link" @click="share(id)" :disabled="saving">Revoke share</button></div></template></section></section>
            <section><h3>Version history</h3><ol class="qms-history"><template x-for="version in versions" :key="version._id"><li><button type="button" class="qms-link" @click="inspect(version, false)" x-text="`Version ${version.versionNumber} · ${version.title}`"></button><small x-text="date(version.createdAt)"></small></li></template></ol><h3>Access &amp; activity history</h3><ol class="qms-history"><template x-for="(entry, index) in activity" :key="index"><li><strong x-text="entry.action"></strong><small x-text="`${entry.actor || 'Authorized account'} · ${date(entry.at)}`"></small></li></template></ol><p x-show="!activity.length">No activity has been recorded yet.</p></section></div></div><footer><button type="button" class="qms-button" @click="$refs.details.close()">Close</button></footer></div></template></dialog>
    <dialog class="qms-dialog qms-upload" x-ref="upload" aria-labelledby="qms-upload-title"><form x-ref="uploadForm" @submit.prevent="save"><header><div><p class="qms-eyebrow">Authorized archive record</p><h2 id="qms-upload-title" x-text="previous ? 'Add document version' : 'Add archive record'"></h2></div><button type="button" class="qms-close" @click="$refs.upload.close()" aria-label="Close add record">×</button></header><div class="qms-dialog-body"><p class="qms-alert" role="alert" x-show="error" x-text="error"></p><div class="qms-form-grid"><label>Department / office<select x-model="form.unitId" @change="form.categoryId=''" :disabled="!!previous" required><option value="">Select folder</option><template x-for="unit in tree.units.filter(unit => unit.canCreate)" :key="unit._id"><option :value="unit._id" x-text="unit.name"></option></template></select></label><label>Category<select x-model="form.categoryId" required><option value="">Select category</option><template x-for="category in formCategories" :key="category._id"><option :value="category._id" x-text="`${category.code} ${category.name}`"></option></template></select></label><label class="qms-full">Document title<input x-model="form.title" required maxlength="255"></label><label>Presentation method<select x-model="form.recordType" :disabled="!!previous"><option value="file">Authorized digital file</option><option value="digital-reference">Digital document reference</option><option value="physical-original">Physical original requiring signature</option></select></label><label>Visibility<select x-model="form.visibility" :disabled="!!previous"><option value="owner">Owner and explicit permissions</option><option value="department">Authorized department accounts</option><option value="college">Authorized college and department accounts</option><option value="restricted">Restricted</option></select></label><label class="qms-full">Description<textarea x-model="form.description" rows="2" maxlength="3000"></textarea></label><label class="qms-full" x-show="form.recordType === 'file'">Digital file<input x-ref="file" type="file" accept=".pdf,.docx,.png,.jpg,.jpeg" :required="form.recordType === 'file'"><small>PDF, Word, PNG, or JPEG · maximum 20 MB · encrypted at rest</small></label><label class="qms-full" x-show="form.recordType === 'digital-reference'">Document reference<input x-model="form.documentReference" :required="form.recordType === 'digital-reference'" maxlength="500" placeholder="Controlled document code or authorized location"></label><label class="qms-full" x-show="form.recordType === 'physical-original'">Location of signed original<input x-model="form.physicalLocation" :required="form.recordType === 'physical-original'" maxlength="500" placeholder="Office, cabinet, register, and document reference"><small>No scan is required. Signature verification remains pending authorized review.</small></label><label class="qms-full qms-checkbox" x-show="form.recordType === 'file'"><input type="checkbox" x-model="form.copyAuthorized" :required="form.recordType === 'file'">I am authorized to upload a digital copy of this document.</label><label class="qms-full qms-checkbox" x-show="form.recordType === 'file'"><input type="checkbox" x-model="form.downloadAllowed" :disabled="!!previous">Allow preview and download for authorized accounts</label></div><p x-show="previous" class="qms-scope-note">Existing permissions are inherited. Earlier versions and their audit links remain unchanged.</p></div><footer><button type="button" class="qms-button" @click="$refs.upload.close()">Cancel</button><button type="submit" class="qms-button qms-gold" :disabled="saving" x-text="saving ? 'Saving…' : 'Save record'"></button></footer></form></dialog>
    <dialog class="qms-dialog qms-upload" x-ref="organization" aria-labelledby="qms-organization-title"><form @submit.prevent="assign"><header><h2 id="qms-organization-title">Archive responsibilities</h2><button type="button" class="qms-close" @click="$refs.organization.close()" aria-label="Close responsibilities">×</button></header><div class="qms-dialog-body"><p class="qms-alert" role="alert" x-show="error" x-text="error"></p><template x-if="organization"><div class="qms-form-grid"><label class="qms-full">Account<select x-model="selectedUser" @change="selectUser" required><option value="">Select account</option><template x-for="user in organization.users.filter(user => Number(user.roleId) !== 2)" :key="user._id"><option :value="user._id" x-text="`${user.name} (${user.email})`"></option></template></select></label><label class="qms-full">Organizational responsibility<select x-model="responsibility"><template x-for="role in organization.responsibilities" :key="role"><option :value="role" x-text="label(role)"></option></template></select></label><fieldset class="qms-full" x-show="['college_dean', 'college_secretary', 'cluster_administrator'].includes(responsibility)"><legend>Explicitly authorized colleges</legend><template x-for="college in tree.colleges" :key="college._id"><label class="qms-checkbox"><input type="checkbox" :value="college._id" x-model="scopeColleges"><span x-text="college.name"></span></label></template></fieldset><fieldset class="qms-full" x-show="!['college_dean', 'college_secretary', 'cluster_administrator'].includes(responsibility)"><legend>Explicitly authorized departments / offices</legend><template x-for="unit in tree.units" :key="unit._id"><label class="qms-checkbox"><input type="checkbox" :value="unit._id" x-model="scopeUnits"><span x-text="unit.name"></span></label></template></fieldset><p class="qms-full qms-scope-note">The account's existing department remains its home assignment. Authentication roles are unchanged. Auditors receive evidence only through authorized audit sharing.</p></div></template></div><footer><button type="button" class="qms-button" @click="$refs.organization.close()">Cancel</button><button type="submit" class="qms-button qms-gold" :disabled="saving || !selectedUser">Save responsibility</button></footer></form></dialog>
</section>
@include('auditee.evidence-preview-modal', ['closeLabel' => 'Close preview'])
